artifacts.content:
query CofounderAnnouncementBarCurrentUserRole {
  currentUserRole {
    id
    cowork {
      ...CofounderAnnouncementBarCowork
      __typename
    }
    __typename
  }
}

fragment CofounderAnnouncementBarCowork on Cowork {
  id
  segmentation {
    id
    accountingConnection
    workforce
    __typename
  }
  settings {
    id
    onboardingStatus
    __typename
  }
  __typename
}

query CompanyOnboardingAndFromDirectSegment {
  company {
    ...CompanyOnboardingAndFromDirectSegmentFields
    __typename
  }
}

fragment CompanyOnboardingAndFromDirectSegmentFields on Company {
  id
  fromDirectSegment
  hasBecomePayingCustomer
  __typename
}

mutation CreateMemberExpense($input: CreateMemberExpenseInput!) {
  payload: createMemberExpense(input: $input) {
    errors {
      argument
      message
    }
    oneTimeReimbursement {
      ...TeamExpense
    }
  }
}

fragment Expense on OneTimeReimbursement {
  id
  amount
  approvedBy
  categoryName
  categoryUuid
  checkDate
  createdAt
  currency
  description
  displayName
  eorOneTimeReimbursement {
    id
    category
    title
  }
  member {
    id
    latestEmployment {
      id
      isEor
      workerType
    }
    preferredFullName
  }
  purchaseDate
  rateData {
    amount
    categoryRateUuid
    name
    rateBaseKind
    rateConversionAmount
  }
  receipt {
    id
    contentType
    name
    url
  }
  status
  statusReason
  vendor {
    id
    name
  }
}

fragment TeamExpense on OneTimeReimbursement {
  availableActions
  ...Expense
}

query DashboardApisUseCurrentCompanySubscriptions {
  company {
    ...DashboardApisUseCurrentCompanySubscriptionsFields
    __typename
  }
}

fragment DashboardApisUseCurrentCompanySubscriptionsFields on Company {
  id
  subscriptions {
    edges {
      node {
        id
        name
        product {
          id
          marketingProduct {
            name
            __typename
          }
          namespace
          productFamilies
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

query FirmLogo($isAccountant: Boolean!) {
  accountingFirm @include(if: $isAccountant) {
    id
    logoUrl
    __typename
  }
  company @skip(if: $isAccountant) {
    id
    managingAccountingFirmLogoUrl
    __typename
  }
}

query GetCurrentCompanyOnboardingExperienceType {
  company {
    id
    companyOnboardingCurrentExperienceType
    hasAccountingFirm
    isOnboarding
    ...OnboardingAdvisorCustomerType
    __typename
  }
  currentUser {
    id
    accountant {
      id
      __typename
    }
    __typename
  }
}

fragment OnboardingAdvisorCustomerType on Company {
  id
  companyProfileAndIntent {
    id
    newToRunningPayroll
    __typename
  }
  __typename
}

query GustoFfe($input: [GustoFfeFeatureInput!]!) {
  gustoFfeFeatures(input: $input) {
    ...GustoFeatureFlagExperimentationFeatureEnabledAndVariableFields
    __typename
  }
}

fragment GustoFeatureFlagExperimentationFeatureEnabledAndVariableFields on GustoFfeFeatureResult {
  __typename
  entityId
  entityType
  featureFlagKey
  featureVariables {
    __typename
    ... on StringFeatureVariable {
      stringVariableValue: variableValue
      variableKey
      __typename
    }
    ... on IntFeatureVariable {
      intVariableValue: variableValue
      variableKey
      __typename
    }
    ... on FloatFeatureVariable {
      floatVariableValue: variableValue
      variableKey
      __typename
    }
    ... on BooleanFeatureVariable {
      booleanVariableValue: variableValue
      variableKey
      __typename
    }
    ... on JsonFeatureVariable {
      jsonVariableValue: variableValue
      variableKey
      __typename
    }
  }
  isFeatureEnabled
  projectEntity
  variationName
}

query MemberExpenses($after: String, $first: Int) {
  member {
    id
    expenses {
      expenses(after: $after, first: $first, filter: {}, order: "-created_at") {
        nodes {
          id
          amount
          approvedBy
          categoryName
          categoryUuid
          checkDate
          createdAt
          currency
          description
          displayName
          purchaseDate
          status
          statusReason
          member {
            id
          }
          receipt {
            id
            contentType
            name
          }
          vendor {
            id
            name
          }
        }
        pageInfo {
          endCursor
          hasNextPage
          hasPreviousPage
        }
      }
    }
  }
}

query ReferralsNavLinkContainer {
  currentUser {
    id
    referralRewards {
      id
      isPromotional
      maxReferrerDollarAmount
      referrerRewardType
      __typename
    }
    referrals {
      id
      unreadReferralsCount
      __typename
    }
    __typename
  }
}

query ReimbursementOptions {
  member {
    id
    expenses {
      categories {
        id
        name
        isDisabled
        rates {
          nodes {
            id
            name
            isActive
            rateBaseKind
            rateConversionAmount
          }
        }
      }
    }
  }
}

query SupportPage($canReadCompanyAddresses: Boolean!, $companyId: ID!, $featureFlagInputs: [GustoFfeFeatureInput!]!, $isAccountant: Boolean!, $isPayrollAdmin: Boolean!) {
  accountant @include(if: $isAccountant) {
    id
    accountingFirm {
      id
      partnerProgramInfo {
        currentLevel
        discountedClientsCount
        __typename
      }
      phone
      __typename
    }
    email
    firstName
    lastName
    phone
    __typename
  }
  company {
    id
    dedicatedSupportContact @include(if: $isPayrollAdmin) {
      id
      __typename
    }
    dsaChatEnabled @include(if: $isPayrollAdmin)
    filingAddress @include(if: $canReadCompanyAddresses) {
      id
      state
      __typename
    }
    fractionalHrPartners @include(if: $isPayrollAdmin) {
      id
      email
      name
      __typename
    }
    hasRunPayroll @include(if: $isPayrollAdmin)
    isApproved
    isEmbeddedPayrollCompany
    isOnboarding
    isSuspended
    premiumFreeTrialStatus @include(if: $isPayrollAdmin) {
      daysRemaining
      onTrial
      __typename
    }
    __typename
  }
  currentUser @include(if: $isPayrollAdmin) {
    id
    isHrSupportCenterUser(companyId: $companyId)
    __typename
  }
  currentUserRole @include(if: $isPayrollAdmin) {
    id
    phone
    __typename
  }
  employee {
    id
    nextPayDay
    __typename
  }
  gustoFfeFeatures(input: $featureFlagInputs) {
    ...GustoFeatureFlagExperimentationFeatureEnabledAndVariableFields
    __typename
  }
  member {
    id
    currentHomeLocation {
      id
      country
      __typename
    }
    currentWorkLocation {
      id
      country
      __typename
    }
    __typename
  }
  supportInfo {
    id
    emailRestrictionEnabled
    miawIdentityToken
    phoneNumber
    prioritySupport
    ...DefaultQuickActions
    ...HoopData
    ...SearchOptions
    ...TechnicalAccountManager
    __typename
  }
}

fragment DefaultQuickActions on SupportInfo {
  defaultQuickActions {
    chatSkill
    href
    keywords
    phoneSkill
    tagIconType
    tagText
    title
    __typename
  }
  __typename
}

fragment GustoFeatureFlagExperimentationFeatureEnabledAndVariableFields on GustoFfeFeatureResult {
  __typename
  entityId
  entityType
  featureFlagKey
  featureVariables {
    __typename
    ... on StringFeatureVariable {
      stringVariableValue: variableValue
      variableKey
      __typename
    }
    ... on IntFeatureVariable {
      intVariableValue: variableValue
      variableKey
      __typename
    }
    ... on FloatFeatureVariable {
      floatVariableValue: variableValue
      variableKey
      __typename
    }
    ... on BooleanFeatureVariable {
      booleanVariableValue: variableValue
      variableKey
      __typename
    }
    ... on JsonFeatureVariable {
      jsonVariableValue: variableValue
      variableKey
      __typename
    }
  }
  isFeatureEnabled
  projectEntity
  variationName
}

fragment HoopData on SupportInfo {
  id
  closures {
    channelName
    daysClosed
    endAt
    eventTitle
    returnAt
    startAt
    teamName
    __typename
  }
  hoop {
    channel
    supportTeam
    weeklyHours {
      closeAt
      isClosed
      isHoliday
      openAt
      weekdayIndex
      __typename
    }
    __typename
  }
  nextAvailableHoop
  supportTeamForUserRole
  __typename
}

fragment SearchOptions on SupportInfo {
  searchOptions {
    popularSearchOptions {
      label
      value
      __typename
    }
    suggestedSearchOptions {
      label
      value
      __typename
    }
    __typename
  }
  __typename
}

fragment TechnicalAccountManager on SupportInfo {
  dsaAvailableForLiveChat
  salesAccountManager {
    email
    firstName
    lastName
    phoneExtension
    salesforceAccountId
    salesforceResellerAccountId
    __typename
  }
  technicalAccountManager {
    email
    firstName
    lastName
    phoneExtension
    salesforceAccountId
    salesforceResellerAccountId
    __typename
  }
  __typename
}

query TopBarCompany($isPayrollAdmin: Boolean!) {
  company {
    id
    shouldShowBenefitsMaintenance
    __typename
  }
  currentUser {
    id
    accountant @include(if: $isPayrollAdmin) {
      id
      __typename
    }
    __typename
  }
}

query UseAdminOverrideRedirect {
  company {
    id
    companyOnboardingMigration {
      id
      migrationState
      migrationType
      __typename
    }
    __typename
  }
  payrollAdmin {
    id
    currentRoleNeedsSelfOnboarding
    currentRoleNeedsSelfOnboardingWelcome
    __typename
  }
}
